From 15b43454739751c2cfe67eb798341d84815bacc6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:13:49 +0100
Subject: [PATCH] kcm: add an option for virtual surround sound on PipeWire

PipeWire can render 5.1 and 7.1 audio as surround sound on headphones,
but there was no way to enable it from Plasma. Add a Configure menu
entry that sets up its spatializer filter with the system's HRTF data.

BUG: 527041
---
 src/kcm/ui/main.qml   |  15 ++++-
 src/modulemanager.cpp | 141 ++++++++++++++++++++++++++++++++++++++++++
 src/modulemanager.h   |   6 ++
 3 files changed, 159 insertions(+), 3 deletions(-)

diff --git a/src/kcm/ui/main.qml b/src/kcm/ui/main.qml
index 140954d7..725e94eb 100644
--- a/src/kcm/ui/main.qml
+++ b/src/kcm/ui/main.qml
@@ -89,25 +89,34 @@ KCM.ScrollViewKCM {
         },
         Kirigami.Action {
             id: configureButton
-            visible: moduleManager.settingsSupported
-            enabled: moduleManager.configModuleLoaded
+            visible: moduleManager.settingsSupported || moduleManager.virtualSurroundSupported
+            enabled: moduleManager.configModuleLoaded || moduleManager.virtualSurroundSupported
             text: i18nd("kcm_pulseaudio", "Configure…")
             icon.name: "configure"

-            tooltip: i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName)
+            tooltip: moduleManager.settingsSupported ? i18nd("kcm_pulseaudio", "Requires %1 PulseAudio module", moduleManager.configModuleName) : ""

             Kirigami.Action {
                 text: i18nd("kcm_pulseaudio", "Add virtual output device for simultaneous output on all local sound cards")
+                visible: moduleManager.settingsSupported
                 checkable: true
                 checked: moduleManager.combineSinks
                 onToggled: moduleManager.combineSinks = checked
             }
             Kirigami.Action {
                 text: i18nd("kcm_pulseaudio", "Automatically switch all running streams when a new output becomes available")
+                visible: moduleManager.settingsSupported
                 checkable: true
                 checked: moduleManager.switchOnConnect
                 onToggled: moduleManager.switchOnConnect = checked
             }
+            Kirigami.Action {
+                text: i18nd("kcm_pulseaudio", "Add virtual output device for surround sound on headphones")
+                visible: moduleManager.virtualSurroundSupported
+                checkable: true
+                checked: moduleManager.virtualSurround
+                onToggled: moduleManager.virtualSurround = checked
+            }
         }
     ]

diff --git a/src/modulemanager.cpp b/src/modulemanager.cpp
index ffe98bb4..61889006 100644
--- a/src/modulemanager.cpp
+++ b/src/modulemanager.cpp
@@ -9,13 +9,117 @@
 #include <PulseAudioQt/Module>
 #include <PulseAudioQt/Server>

+#include "debug.h"
 #include "gsettingsitem.h"
 #define PA_SETTINGS_PATH_MODULES "/org/freedesktop/pulseaudio/module-groups"

+#include <KLocalizedString>
+
+#include <QDir>
+#include <QFile>
+#include <QFileInfo>
+#include <QProcess>
+#include <QStandardPaths>
 #include <QTimer>
 #include <chrono>

 using namespace std::chrono_literals;
+using namespace Qt::StringLiterals;
+
+namespace
+{
+QString virtualSurroundConfigPath()
+{
+    return QStandardPaths::writableLocation(QStandardPaths::GenericConfigLocation) + u"/pipewire/pipewire.conf.d/plasma-pa-virtual-surround.conf"_s;
+}
+
+QString virtualSurroundHrtfPath()
+{
+    return QStandardPaths::locate(QStandardPaths::GenericDataLocation, u"libmysofa/default.sofa"_s);
+}
+
+// PipeWire filter-chain that places each 7.1 channel around the listener with the
+// sofa spatializer and mixes the result down to stereo for headphones.
+QByteArray virtualSurroundConfig()
+{
+    struct Speaker {
+        QString channel;
+        double azimuth;
+        double elevation;
+    };
+    const Speaker speakers[] = {
+        {u"FL"_s, 30, 0},
+        {u"FR"_s, 330, 0},
+        {u"FC"_s, 0, 0},
+        {u"LFE"_s, 0, -60},
+        {u"RL"_s, 150, 0},
+        {u"RR"_s, 210, 0},
+        {u"SL"_s, 90, 0},
+        {u"SR"_s, 270, 0},
+    };
+
+    QString nodes;
+    QString links;
+    QStringList inputs;
+    QStringList positions;
+    const QString hrtfPath = virtualSurroundHrtfPath();
+    int mixerInput = 1;
+    for (const Speaker &speaker : speakers) {
+        nodes +=
+            uR"(
+                    { type = sofa label = spatializer name = sp%1
+                        config = { filename = "%2" gain = 0.5 }
+                        control = { "Azimuth" = %3 "Elevation" = %4 "Radius" = 3.0 } })"_s.arg(speaker.channel, hrtfPath)
+                .arg(speaker.azimuth)
+                .arg(speaker.elevation);
+        links +=
+            uR"(
+                    { output = "sp%1:Out L" input = "mixL:In %2" }
+                    { output = "sp%1:Out R" input = "mixR:In %2" })"_s.arg(speaker.channel)
+                .arg(mixerInput++);
+        inputs += u"\"sp%1:In\""_s.arg(speaker.channel);
+        positions += speaker.channel;
+    }
+
+    const QString description = i18nc("@label name of an output device", "Virtual Surround Sound").replace(u'"', u'\'');
+
+    return uR"(context.modules = [
+    { name = libpipewire-module-filter-chain
+        flags = [ nofail ]
+        args = {
+            node.description = "%1"
+            media.name = "%1"
+            filter.graph = {
+                nodes = [%2
+                    { type = builtin label = mixer name = mixL }
+                    { type = builtin label = mixer name = mixR }
+                ]
+                links = [%3
+                ]
+                inputs = [ %4 ]
+                outputs = [ "mixL:Out" "mixR:Out" ]
+            }
+            capture.props = {
+                node.name = "effect_input.plasma_pa_virtual_surround"
+                media.class = Audio/Sink
+                # WirePlumber would restore only two channel volumes and mute the others
+                state.restore-props = false
+                audio.channels = 8
+                audio.position = [ %5 ]
+            }
+            playback.props = {
+                node.name = "effect_output.plasma_pa_virtual_surround"
+                node.passive = true
+                audio.channels = 2
+                audio.position = [ FL FR ]
+            }
+        }
+    }
+]
+)"_s.arg(description, nodes, links, inputs.join(u' '), positions.join(u' '))
+        .toUtf8();
+}
+} // namespace

 namespace PulseAudioQt
 {
@@ -138,6 +242,43 @@ QString ModuleManager::configModuleName() const
 {
     return QStringLiteral("module-gsettings");
 }
+
+bool ModuleManager::virtualSurroundSupported() const
+{
+    return Context::instance()->server()->isPipeWire() && !virtualSurroundHrtfPath().isEmpty();
+}
+
+bool ModuleManager::virtualSurround() const
+{
+    return QFile::exists(virtualSurroundConfigPath());
+}
+
+void ModuleManager::setVirtualSurround(bool virtualSurround)
+{
+    if (virtualSurround == this->virtualSurround()) {
+        return;
+    }
+
+    const QString path = virtualSurroundConfigPath();
+    if (virtualSurround) {
+        QDir().mkpath(QFileInfo(path).path());
+        QFile file(path);
+        if (!file.open(QFile::WriteOnly | QFile::Truncate) || file.write(virtualSurroundConfig()) == -1) {
+            qCWarning(PLASMAPA) << "Failed to write" << path << file.errorString();
+            file.remove();
+            Q_EMIT virtualSurroundChanged();
+            return;
+        }
+    } else if (!QFile::remove(path)) {
+        qCWarning(PLASMAPA) << "Failed to remove" << path;
+        Q_EMIT virtualSurroundChanged();
+        return;
+    }
+    Q_EMIT virtualSurroundChanged();
+
+    // PipeWire only reads its configuration on startup
+    QProcess::startDetached(u"systemctl"_s, {u"--user"_s, u"restart"_s, u"wireplumber.service"_s, u"pipewire.service"_s});
+}
 }

 #include "moc_modulemanager.cpp"
diff --git a/src/modulemanager.h b/src/modulemanager.h
index 6241f093..f075a3a6 100644
--- a/src/modulemanager.h
+++ b/src/modulemanager.h
@@ -30,6 +30,8 @@ class ModuleManager : public QObject
     Q_PROPERTY(bool configModuleLoaded READ configModuleLoaded NOTIFY loadedModulesChanged)
     Q_PROPERTY(QString configModuleName READ configModuleName CONSTANT)
     Q_PROPERTY(QStringList loadedModules READ loadedModules NOTIFY loadedModulesChanged)
+    Q_PROPERTY(bool virtualSurroundSupported READ virtualSurroundSupported NOTIFY serverUpdated)
+    Q_PROPERTY(bool virtualSurround READ virtualSurround WRITE setVirtualSurround NOTIFY virtualSurroundChanged)
 public:
     explicit ModuleManager(QObject *parent = nullptr);
     ~ModuleManager() override;
@@ -42,12 +44,16 @@ public:
     QStringList loadedModules() const;
     bool configModuleLoaded() const;
     QString configModuleName() const;
+    bool virtualSurroundSupported() const;
+    bool virtualSurround() const;
+    void setVirtualSurround(bool virtualSurround);

 Q_SIGNALS:
     void combineSinksChanged();
     void switchOnConnectChanged();
     void loadedModulesChanged();
     void serverUpdated();
+    void virtualSurroundChanged();

 private:
     void updateLoadedModules();
-- 
